// @minecraft/server の最小スタブ。main.js を Node で実際に読み込み、
// 登録されたハンドラを取り出して呼び出すためだけのもの。
export const GameMode = { Creative: "creative", Survival: "survival" };
export const StructureSaveMode = { World: "World", Memory: "Memory" };
export const EquipmentSlot = { Mainhand: "Mainhand", Offhand: "Offhand" };

export class ItemStack {
  constructor(typeId, amount = 1) {
    this.typeId = typeId;
    this.amount = amount;
  }
}

export class BlockPermutation {
  constructor(typeId, states = {}) {
    this.type = { id: typeId };
    this._states = states;
  }
  getAllStates() {
    return { ...this._states };
  }
  static resolve(typeId, states = {}) {
    return new BlockPermutation(typeId, states);
  }
}

// --- 疑似ワールド --------------------------------------------------------

export const captured = {
  intervals: [],
  jobs: [],
  timeouts: [],
  itemComponents: new Map(),
  events: new Map(),
  messages: [],
  actionBars: [],
  warnings: [],
};

class FakeDimension {
  constructor(id) {
    this.id = id;
    this.blocks = new Map();
    this.particles = [];
    this.droppedItems = [];
  }
  key(l) {
    return `${l.x},${l.y},${l.z}`;
  }
  getBlock(l) {
    const k = this.key(l);
    if (!this.blocks.has(k)) {
      this.blocks.set(k, {
        typeId: "minecraft:air",
        isAir: true,
        location: { ...l },
        dimension: this,
        permutation: new BlockPermutation("minecraft:air"),
        setPermutation(p) {
          this.permutation = p;
          this.typeId = p.type.id;
          this.isAir = p.type.id === "minecraft:air";
        },
      });
    }
    return this.blocks.get(k);
  }
  spawnParticle(id, location) {
    this.particles.push({ id, location });
  }
  spawnItem(itemStack, location) {
    this.droppedItems.push({ itemStack, location });
  }
}

const dimensions = new Map([
  ["minecraft:overworld", new FakeDimension("minecraft:overworld")],
]);

function makeEvent(name) {
  const handlers = [];
  captured.events.set(name, handlers);
  return { subscribe: (fn) => handlers.push(fn) };
}

const worldProps = new Map();

export const world = {
  _props: worldProps,
  getDynamicProperty: (k) => worldProps.get(k),
  setDynamicProperty: (k, v) => (v === undefined ? worldProps.delete(k) : worldProps.set(k, v)),
  getAllPlayers: () => [...players],
  getPlayers: () => [...players],
  getDimension: (id) => dimensions.get(id),
  structureManager: {
    _store: new Map(),
    get(id) {
      return this._store.get(id);
    },
    delete(id) {
      if (!this._store.has(id)) throw new Error("no such structure");
      this._store.delete(id);
    },
    createFromWorld(id, dimension, from, to) {
      const size = {
        x: to.x - from.x + 1,
        y: to.y - from.y + 1,
        z: to.z - from.z + 1,
      };
      // 実物と同じく「保存した瞬間のスナップショット」にする
      const snapshot = new Map();
      for (let y = 0; y < size.y; y++)
        for (let z = 0; z < size.z; z++)
          for (let x = 0; x < size.x; x++) {
            const b = dimension.getBlock({ x: from.x + x, y: from.y + y, z: from.z + z });
            snapshot.set(`${x},${y},${z}`, b ? b.permutation : undefined);
          }
      this._store.set(id, {
        size,
        getBlockPermutation({ x, y, z }) {
          return snapshot.get(`${x},${y},${z}`);
        },
      });
      return this._store.get(id);
    },
  },
  afterEvents: {
    playerPlaceBlock: makeEvent("playerPlaceBlock"),
    playerLeave: makeEvent("playerLeave"),
    playerSpawn: makeEvent("playerSpawn"),
  },
  beforeEvents: {
    playerBreakBlock: makeEvent("playerBreakBlock"),
  },
};

export const system = {
  currentTick: 0,
  runInterval: (fn, ticks) => {
    captured.intervals.push({ fn, ticks });
    return captured.intervals.length;
  },
  clearRun: () => {},
  runTimeout: (fn, ticks) => {
    captured.timeouts.push({ ticks });
    fn(); // テストでは即時実行する
  },
  run: (fn) => fn(),
  runJob: (gen) => {
    captured.jobs.push(gen);
    // テストでは同期的に走らせる
    let n = 0;
    while (!gen.next().done && n++ < 1e7);
  },
  beforeEvents: {
    startup: {
      subscribe: (fn) =>
        fn({
          itemComponentRegistry: {
            registerCustomComponent: (name, comp) => captured.itemComponents.set(name, comp),
          },
        }),
    },
  },
};

// --- 疑似プレイヤー ------------------------------------------------------

export const players = [];

export function makePlayer(name, gameMode = GameMode.Survival) {
  const props = new Map();
  const slots = new Array(36).fill(undefined);
  const player = {
    id: `id_${name}`,
    name,
    _props: props,
    location: { x: 0, y: 64, z: 0 },
    dimension: dimensions.get("minecraft:overworld"),
    isSneaking: false,
    getGameMode: () => gameMode,
    getDynamicProperty: (k) => props.get(k),
    setDynamicProperty: (k, v) => (v === undefined ? props.delete(k) : props.set(k, v)),
    sendMessage: (m) => captured.messages.push(`${name}: ${m}`),
    onScreenDisplay: { setActionBar: (m) => captured.actionBars.push(`${name}: ${m}`) },
    teleport: (loc) => (player.location = { ...loc }),
    getComponent(id) {
      if (id === "minecraft:inventory") {
        return {
          container: {
            size: slots.length,
            getItem: (i) => (slots[i] ? { ...slots[i] } : undefined),
            setItem: (i, item) => (slots[i] = item ? { ...item } : undefined),
            addItem: (stack) => {
              const free = slots.findIndex((s) => s === undefined);
              if (free === -1) return stack; // 満杯なら余りを返す
              slots[free] = { typeId: stack.typeId, amount: stack.amount };
              return undefined;
            },
          },
        };
      }
      if (id === "minecraft:equippable") {
        return { getEquipment: () => (slots[0] ? { ...slots[0] } : undefined) };
      }
      return undefined;
    },
    _give(typeId, amount) {
      slots[0] = { typeId, amount };
    },
    _slots: slots,
  };
  players.push(player);
  return player;
}

export function fakeDimension() {
  return dimensions.get("minecraft:overworld");
}
